/* Claude Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Claude Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 250 248 241;
    --foreground: 61 56 38;
    --card: 250 248 241;
    --card-foreground: 20 20 20;
    --popover: 255 255 255;
    --popover-foreground: 41 39 27;
    --primary: 203 100 65;
    --primary-foreground: 255 255 255;
    --secondary: 231 228 221;
    --secondary-foreground: 82 80 68;
    --muted: 237 232 217;
    --muted-foreground: 133 131 125;
    --accent: 231 228 221;
    --accent-foreground: 41 39 27;
    --destructive: 20 20 20;
    --destructive-foreground: 255 255 255;
    --border: 217 216 208;
    --input: 180 177 163;
    --ring: 27 126 222;
    --chart-1: 178 87 47;
    --chart-2: 156 135 246;
    --chart-3: 222 215 194;
    --chart-4: 218 210 239;
    --chart-5: 178 86 48;
    --radius: 0.5rem;
    --sidebar: 247 245 238;
    --sidebar-foreground: 62 62 56;
    --sidebar-primary: 203 100 65;
    --sidebar-primary-foreground: 252 252 252;
    --sidebar-accent: 231 228 221;
    --sidebar-accent-foreground: 53 53 53;
    --sidebar-border: 235 235 235;
    --sidebar-ring: 180 180 180;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 38 38 38;
    --foreground: 195 193 186;
    --card: 38 38 38;
    --card-foreground: 250 248 241;
    --popover: 48 48 48;
    --popover-foreground: 228 228 228;
    --primary: 216 119 87;
    --primary-foreground: 255 255 255;
    --secondary: 250 248 241;
    --secondary-foreground: 48 48 48;
    --muted: 27 27 27;
    --muted-foreground: 183 181 166;
    --accent: 26 24 19;
    --accent-foreground: 247 245 238;
    --destructive: 241 68 68;
    --destructive-foreground: 255 255 255;
    --border: 62 62 56;
    --input: 81 80 74;
    --ring: 27 126 222;
    --chart-1: 178 87 47;
    --chart-2: 156 135 246;
    --chart-3: 26 24 19;
    --chart-4: 48 44 72;
    --chart-5: 178 86 48;
    --radius: 0.5rem;
    --sidebar: 31 31 31;
    --sidebar-foreground: 195 193 186;
    --sidebar-primary: 53 53 53;
    --sidebar-primary-foreground: 252 252 252;
    --sidebar-accent: 15 15 15;
    --sidebar-accent-foreground: 195 193 186;
    --sidebar-border: 235 235 235;
    --sidebar-ring: 180 180 180;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  }

}
